/* PLAN 060 R16 material_fixes #1 (Astra): (N-1+.8)/n siktade så nära
   stegets EGEN slutpunkt (0,8 av vägen in i steget) att det för Hōrai
   (n=6) hamnade INNE i stegets eget --out-fönster [b-f,b] i stället för
   före det - .cs klipptes redan i förhandsvisningen (steg-h3 delvis
   dold). Math.min(...) håller siktet vid högst N/n-.045, tryggt innanför
   b-f (marginal .005), utan att röra själva --f/--out-formeln i CSS. */
function previewCaseP(N, n){ return Math.min((N - 1 + 0.8) / n, N / n - .045); }
if (mode && /^case-calyx-0[1-5]$/.test(mode)){
  var ccN = parseInt(mode.slice(-1), 10);
  var ccEl = document.getElementById('case-calyx');
  var ccC = CASES.filter(function(C){ return C.el === ccEl; })[0];
  var ccP = previewCaseP(ccN, 5);
  aimPin(ccEl, ccP, function(){
    if (ccC){ if (ccC.y) { var y = caseY(ccC, ccP); if (ccC.w) ccC.w.scrollTo({ top:y, left:0, behavior:'instant' }); } kickLatch(); }
  });
}
if (mode && /^case-horai-0[1-6]$/.test(mode)){
  var chN = parseInt(mode.slice(-1), 10);
  var chEl = document.getElementById('case-horai');
  var chC = CASES.filter(function(C){ return C.el === chEl; })[0];
  var chP = previewCaseP(chN, 6);
  aimPin(chEl, chP, function(){
    if (chC){ if (chC.y) { var y = caseY(chC, chP); if (chC.w) chC.w.scrollTo({ top:y, left:0, behavior:'instant' }); } kickLatch(); }
  });
}

