file.content:
  padding:clamp(16px,3svh,24px) var(--rail-x) 0;}
.case-wrap,.case--calyx .case-wrap,.case--horai .case-wrap{border:0;
  border-bottom:1px solid var(--c-line-on-paper);}
.case-text > .kicker-sans{display:none;}
.case-title{margin-top:0;}
.case-name{font-size:2.25rem;}
/* PLAN 057 3 § Boundaries, löst i R15 (lead-fynd R14, alternativ 1):
   caselinjen fick inte plats vid 390/375 i ALLA steg samtidigt
   (uppmätt R12: upp till -82px, textens sista glyf under stagens
   egen kant) - så länge den stod kvar genom hela sekvensen. Den
   behövs bara i steg 1 (ingen bild där ännu, ramen har inget
   bildkrav att skydda); från steg 2 tar R8-R11:s finjusterade
   bildbudget över. I stället för display:none hela vägen: raden
   syns hel i steg 1 och tonas/faller ihop scrubbat på casets EGEN
   --sc-ps när steg 2 tar över (samma asymmetriska --out-formel som
   .js .cs för steg 0, rad ~965), ingen transition-tid, båda
   riktningarna. Grid-track (inte max-height) för att fälla en
   AUTO-höjd rad utan att mäta den i JS; .case-line-inner bär
   min-height:0 så tracket faktiskt kan gå till 0. h2:ens
   tillgängliga namn (case-name + case-line) är alltid hela den
   låsta meningen ordagrant - ingen display:none/aria-hidden här,
   bara visuellt komprimerad vid steg >=2. */
.case-line{font-size:1.0625rem;line-height:1.3;max-width:none;
  display:grid;overflow:hidden;grid-template-rows:1fr;margin-top:6px;}
.case-line-inner{min-height:0;overflow:hidden;}
.js .case-line{--b:calc(1 / var(--n));--f:.04;
  --out:clamp(0,calc((var(--sc-ps,0) - (var(--b) - var(--f))) / var(--f)),1);
  grid-template-rows:calc((1 - var(--out)) * 1fr);
  opacity:calc(1 - var(--out));
  margin-top:calc((1 - var(--out)) * 6px);}
.case-steps{margin-top:4px;}
.cs h3{font-size:1.25rem;margin-bottom:2px;}
.cs p{font-size:.9375rem;line-height:1.32;max-width:none;}

