from playwright.sync_api import sync_playwright

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"

def h3_clip_check(pg, sel_case, mode):
    pg.goto(f"{URL}?preview={mode}")
    ifr_sel = "#case-horai iframe" if "horai" in mode else "#case-calyx iframe"
    try:
        pg.wait_for_function(
            "(s) => { const el = document.querySelector(s); return el && el.contentWindow && el.contentWindow.scrollY >= 0; }",
            ifr_sel, timeout=15000)
    except Exception:
        pass
    pg.wait_for_timeout(900)
    r = pg.evaluate("""(sel) => {
      const cs = document.querySelector(sel + ' .cs[style*="--i:' + %s + '"]') || null;
      return null;
    }""" % 0)
    r = pg.evaluate("""(sel) => {
      const wrap = document.querySelector(sel);
      const active = Array.from(wrap.querySelectorAll('.cs')).find(el => {
        const cp = getComputedStyle(el).clipPath;
        return cp === 'none' || cp === 'inset(0px)' || cp === 'inset(0px 0px 0px 0px)';
      });
      if (!active) return {found:false};
      const h3 = active.querySelector('h3');
      const h3r = h3.getBoundingClientRect();
      const csR = active.getBoundingClientRect();
      return {found:true, h3top: h3r.top, h3bottom: h3r.bottom, h3height: h3r.height,
              csTop: csR.top, clipTop: csR.top - h3r.top, text: h3.textContent};
    }""", sel_case)
    return r

with sync_playwright() as p:
    b = p.chromium.launch()
    for w,h in [(1920,930),(1440,900),(390,844)]:
        pg = b.new_page(viewport={"width":w,"height":h})
        for n in range(1,7):
            mode = f"case-horai-0{n}"
            r = h3_clip_check(pg, ".case--horai", mode)
            print(w, mode, r)
        pg.close()
    b.close()

