from playwright.sync_api import sync_playwright

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"

with sync_playwright() as p:
    b = p.chromium.launch()
    for w, h in [(390, 844), (375, 812)]:
        pg = b.new_page(viewport={"width": w, "height": h})
        for case, n_steps in [("calyx", 5), ("horai", 6)]:
            sel_iframe = "#case-%s iframe" % case
            for n in range(1, n_steps + 1):
                mode = "case-%s-0%d" % (case, n)
                pg.goto(URL + "?preview=" + mode)
                try:
                    pg.wait_for_function(
                        "(s) => { const el = document.querySelector(s); return el && el.contentWindow && el.contentWindow.scrollY >= 0; }",
                        sel_iframe, timeout=15000)
                except Exception:
                    pass
                pg.wait_for_timeout(900)
                r = pg.evaluate("""(sel) => {
                  const sec = document.querySelector(sel);
                  const stage = sec.querySelector('.case-stage');
                  const stageRect = stage.getBoundingClientRect();
                  const active = Array.from(sec.querySelectorAll('.cs')).find(el => {
                    const cp = getComputedStyle(el).clipPath;
                    return cp === 'none' || cp === 'inset(0px)' || cp === 'inset(0px 0px 0px 0px)';
                  });
                  if (!active) return {found:false};
                  const p = active.querySelector('p');
                  const range = document.createRange();
                  range.selectNodeContents(p);
                  const rects = range.getClientRects();
                  const lastRect = rects[rects.length-1];
                  const caseLine = sec.querySelector('.case-line');
                  const clRect = caseLine.getBoundingClientRect();
                  return {
                    margin: Math.round(stageRect.bottom - lastRect.bottom),
                    caseLineHeight: Math.round(clRect.height),
                    caseLineOpacity: getComputedStyle(caseLine).opacity,
                  };
                }""", ".case--" + case)
                print(w, case, n, r)
        pg.close()
    b.close()

